	var cim := CanvasItemMaterial.new(); cim.blend_mode = CanvasItemMaterial.BLEND_MODE_ADD
	var p := GPUParticles2D.new(); p.process_material = m; p.material = cim; p.emitting = false
	var ps := PackedScene.new(); ps.pack(p)
	print(ResourceSaver.save(ps, "user://probe.tscn"))
